<script setup lang="ts">
import {computed,onMounted,onUnmounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';
const {pcmRecorder:recorder}=useApplication(),route=useRoute(),router=useRouter();const visible=computed(()=>route.name!=='recording'&&!!recorder.record.value&&!recorder.record.value.finished&&(recorder.record.value.parts.length>0||['RECORDING','PAUSED','SAVING'].includes(recorder.phase.value)));
const clock=computed(()=>{const t=Math.floor(recorder.elapsed.value/1000);return `${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t/60)%60).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;});
const marker=computed(()=>({RECORDING:['正在录音',''],PAUSED:['录音已暂停','Ⅱ'],INTERRUPTED:['本段已中断','■'],SAVING:['录音保存中','…'],ERROR:['录音异常','!']}[recorder.phase.value]??['等待麦克风授权','']));
function online(){if(recorder.record.value&&!recorder.record.value.finished)void recorder.reconnect().catch(()=>{});}
function beforeUnload(event:BeforeUnloadEvent){if(['RECORDING','PAUSED','SAVING','AUTHORIZING','ERROR'].includes(recorder.phase.value)&&recorder.record.value&&!recorder.record.value.finished){event.preventDefault();event.returnValue='';}}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('online',online);});onUnmounted(()=>{window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('online',online);});
</script>
<template><button v-if="visible" class="acr-floating-recording" :class="{'is-paused':recorder.phase.value!=='RECORDING','is-saving':recorder.phase.value==='SAVING','has-error':recorder.phase.value==='ERROR'}" :aria-label="marker[0]+' '+clock+'，点击返回在线录音'" :title="marker[0]+' '+clock+' · 点击返回'" @click="router.push('/recording/'+recorder.record.value!.meetingId)"><span class="acr-floating-ring"></span><Icon name="mic" :size="23"/><span class="acr-floating-state">{{marker[1]}}</span><span class="acr-floating-tip" role="tooltip">{{marker[0]}} · {{clock}}　返回录音页</span></button></template>
